/**
 * Purchase order numbers, e.g. "PO-SEA-20261102-001" (outlet prefix, India date, running number).
 * Generated by the backend (alayn-backend src/utils/poNumber.ts); the same number shows in the
 * supplier portal and in notifications.
 */
export function formatPONumber(po: { poNumber?: string | null }): string | null {
  return po.poNumber || null;
}

/** True when a search like "001", "20261102-001" or "po-sea-20261102" is part of this PO's number. */
export function matchesPONumber(po: { poNumber?: string | null }, query: string): boolean {
  const q = query.trim().toLowerCase();
  return !!q && !!po.poNumber && po.poNumber.toLowerCase().includes(q);
}
